import { test } from "node:test";
import assert from "node:assert/strict";
import { HookBus } from "../src/bus.ts";
import { registerAuditPlugin } from "../src/plugin.ts";

test("emit waits for each handler in subscription order", async () => {
  const bus = new HookBus();
  const seen: string[] = [];
  let release!: () => void;
  const gate = new Promise<void>((resolve) => { release = resolve; });
  bus.on("event", async () => {
    seen.push("first:start");
    await gate;
    seen.push("first:end");
  });
  bus.on("event", () => { seen.push("second"); });
  const pending = bus.emit("event", null);
  assert.deepEqual(seen, ["first:start"]);
  release();
  await pending;
  assert.deepEqual(seen, ["first:start", "first:end", "second"]);
});

test("subscription changes take effect on the next emit", async () => {
  const bus = new HookBus();
  const seen: string[] = [];
  const stopFirst = bus.on("event", () => {
    seen.push("first");
    stopFirst();
    stopSecond();
    bus.on("event", () => { seen.push("new"); });
  });
  const stopSecond = bus.on("event", () => { seen.push("second"); });
  await bus.emit("event", null);
  assert.deepEqual(seen, ["first", "second"]);
  await bus.emit("event", null);
  assert.deepEqual(seen, ["first", "second", "new"]);
});

for (const asynchronous of [false, true]) {
  test(`emit propagates the same ${asynchronous ? "async" : "sync"} error and stops`, async () => {
    const bus = new HookBus();
    const failure = new Error("hook failure");
    let laterRan = false;
    bus.on("event", asynchronous
      ? async () => { throw failure; }
      : () => { throw failure; });
    bus.on("event", () => { laterRan = true; });
    await assert.rejects(bus.emit("event", null), (error) => error === failure);
    assert.equal(laterRan, false);
  });
}

test("audit plugin redacts before logging and shows its notice once", async () => {
  const bus = new HookBus();
  const audit: string[] = [];
  registerAuditPlugin(bus, audit);
  await bus.emit("tool.after", { tool: "read", output: "password=example" });
  await bus.emit("tool.after", { tool: "write", output: "password=another" });
  assert.deepEqual(audit, [
    "notice: tool output is audited",
    "read: password=[redacted]",
    "write: password=[redacted]",
  ]);
});


